#include <iostream>
#include <string>
using namespace std;

int locate_substring(const string& str, const string& pattern, int start_idx) {
    for (int i = start_idx; i <= (int)str.length() - (int)pattern.length(); ++i) {
        if (str[i] == pattern[0]) {
            bool match_found = true;
            for (int j = 1; j < (int)pattern.length(); ++j) {
                if (str[i + j] != pattern[j]) {
                    match_found = false;
                    break;
                }
            }
            if (match_found) return i;
        }
    }
    return -1;
}

int main() {
    string email, temp, output;
    cin >> email;
    int at_pos = locate_substring(email, "at", 1);
    temp = email.substr(0, at_pos) + '@' + email.substr(at_pos + 2);
    int dot_pos = locate_substring(temp, "dot", 1);
    int start_idx = 0;
    while (dot_pos != -1 && dot_pos < (int)temp.size() - 3) {
        output += temp.substr(start_idx, dot_pos - start_idx) + ".";
        start_idx = dot_pos + 3;
        dot_pos = locate_substring(temp, "dot", start_idx);
    }
    output += temp.substr(start_idx);
    cout << output;
    return 0;
}
